import { lazy } from 'react';
import { IndianRupee as IcIndianRupee, Scale as IcScale, TrendingUp as IcTrendingUp } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Talent Decisions — hub page for the Performance menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 3 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'TalentDecisions'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const CalibrationCenter = lazy(() => import('./CalibrationCenter'));
const IncrementPlanning = lazy(() => import('./IncrementPlanning'));
const PromotionPlanning = lazy(() => import('./PromotionPlanning'));

export const TABS = [
  { id: 'calibration', label: 'Calibration', icon: IcScale, page: 'CalibrationCenter', Component: CalibrationCenter },
  { id: 'increment', label: 'Increment Planning', icon: IcIndianRupee, page: 'IncrementPlanning', Component: IncrementPlanning },
  { id: 'promotion', label: 'Promotion Planning', icon: IcTrendingUp, page: 'PromotionPlanning', Component: PromotionPlanning },
];

export default function TalentDecisions({ setPage }) {
  return (
    <TabHub
      icon={IcScale}
      eyebrow="Performance"
      title="Talent Decisions"
      subtitle="Rating calibration, increment planning and promotion planning"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
